    GRID_COLS,
    GRID_ROWS,
    CELL_TYPES,
    isGroundCellType,
    clampTreeAge,
    getTreeAgeLabel,
    getTreeAgeClass,
    createDefaultSelectedPixelPreview,
    createSelectedPixelPreview,
